<?php
declare(strict_types=1);require_once __DIR__.'/src/auth.php';require_admin();$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='add'){try{$s=$pdo->prepare('INSERT INTO access_logs(student_id,login_time,access_type,status,device_id,user_type) VALUES(?,?,?,?,?,?)');$sid=trim($_POST['student_id']??'');$time=$_POST['login_time']?:date('Y-m-d H:i:s');$time=str_replace('T',' ',$time);$s->execute([$sid!==''?$sid:null,$time,$_POST['access_type'],$_POST['status'],trim($_POST['device_id']),$_POST['user_type']]);$msg='Access log saved.';}catch(PDOException $e){$err='Could not save access log. Check Student ID.';}}
$students=$pdo->query('SELECT student_id,username FROM students WHERE is_active=1 ORDER BY student_id')->fetchAll();$rows=$pdo->query('SELECT a.*,s.username FROM access_logs a LEFT JOIN students s ON s.student_id=a.student_id ORDER BY a.login_time DESC')->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Access Logs</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"><link href="assets/style.css" rel="stylesheet"></head><body><?php include __DIR__.'/partials/navbar.php';?><div class="container-fluid"><div class="row"><?php include __DIR__.'/partials/sidebar.php';?><main class="col-lg-10 p-4"><h1 class="fw-bold">Access Logs</h1><p class="text-muted">Store entry and exit events in MySQL.</p><?php if($msg):?><div class="alert alert-success"><?=h($msg)?></div><?php endif;?><?php if($err):?><div class="alert alert-danger"><?=h($err)?></div><?php endif;?><div class="card border-0 shadow-sm mb-4"><div class="card-header bg-white"><h5>Add Access Log</h5></div><div class="card-body"><form method="post" class="row g-3"><input type="hidden" name="action" value="add"><div class="col-md-3"><label class="form-label">Student</label><select name="student_id" class="form-select"><option value="">Unknown person</option><?php foreach($students as $s):?><option value="<?=h($s['student_id'])?>"><?=h($s['student_id'].' - '.$s['username'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Date & Time</label><input type="datetime-local" name="login_time" class="form-control"></div><div class="col-md-2"><label class="form-label">Access Type</label><select name="access_type" class="form-select"><option>Entry</option><option>Exit</option></select></div><div class="col-md-2"><label class="form-label">Status</label><select name="status" class="form-select"><option>SUCCESS</option><option>FAILED</option></select></div><div class="col-md-2"><label class="form-label">Device ID</label><input name="device_id" class="form-control" value="SCAN01" required></div><div class="col-md-1"><label class="form-label">User</label><select name="user_type" class="form-select"><option>Student</option><option>Unknown</option><option>Staff</option></select></div><div class="col-12"><button class="btn btn-primary">Save Log</button></div></form></div></div><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Log ID</th><th>Student ID</th><th>Username</th><th>Time</th><th>Type</th><th>Status</th><th>Device</th><th>User Type</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h((string)$r['log_id'])?></td><td><?=h((string)($r['student_id']??'NULL'))?></td><td><?=h((string)($r['username']??'Unknown'))?></td><td><?=h($r['login_time'])?></td><td><?=h($r['access_type'])?></td><td><?=h($r['status'])?></td><td><?=h($r['device_id'])?></td><td><?=h($r['user_type'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8" class="text-center text-muted py-4">No access logs yet.</td></tr><?php endif;?></tbody></table></div></div></main></div></div></body></html>